package com.example.rokidkeyboardbridge;
public final class CharacterContinuityTest {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static void main(String[] args){
 for(String seat:new String[]{"座って","ねそべって","くつろいで"}){EmbodiedScenePolicy p=new EmbodiedScenePolicy();p.user(seat,1000);int clip=p.clip(1100,false);p.answer("分かりました。",FullBodyPoseCatalog.Kind.NEUTRAL,1200);for(String q:new String[]{"明日の天気は？","どういう意味？","私は今日は疲れたよ","続きを聞かせて"}){ok(p.carries(q),"ordinary followup carries posture");p.user(q,2000);p.answer("お話ししましょう。",FullBodyPoseCatalog.Kind.NEUTRAL,2200);ok(p.stable(),"stable posture remains");if(clip>=0)ok(p.clip(200000,false)==clip,"no 90 second posture expiry");else ok(p.posture()==1,"seated base kept");}p.user("立って",300000);ok(p.posture()==0,"explicit stand replaces posture");}
 EmbodiedScenePolicy p=new EmbodiedScenePolicy();p.user("座って",1000);p.user("ねそべって",2000);p.user("動いてない",2100);ok(p.clip(2200,false)==28,"replay lying");p.answer("やり直します。",FullBodyPoseCatalog.Kind.NEUTRAL,2300);p.user("戻って",2400);p.user("戻って",2500);ok(p.posture()==1&&p.clip(2600,false)!=28,"duplicate TTS context does not undo twice");p.answer("戻します。",FullBodyPoseCatalog.Kind.NEUTRAL,2700);p.user("戻って",2800);ok(p.clip(2900,false)==28,"next user undo works");p.user("微笑んで",3000);ok(p.clip(3100,false)==28&&p.face()==1,"smile keeps lying body");p.user("手を振って",3200);ok(p.clip(3300,false)==29&&p.selected(3300)==5,"lying wave uses lying artwork");p.user("座って",4000);p.user("手を振って",4100);ok(p.clip(4200,false,true)==1,"seated wave stays seated");ok(p.posture()==1,"wave preserves seated base");
 for(String q:new String[]{"駅まで戻って案内して","彼女が動いてないと言った","戻ってとはどういう意味？","その姿勢じゃないかもしれない"})ok(VisualRepairIntent.kind(q)==0,"not display control");
 for(String initial:new String[]{"座って","ねそべって"}){EmbodiedScenePolicy shortMotion=new EmbodiedScenePolicy();shortMotion.user(initial,1000);shortMotion.user("照れて身をよじって",2000);shortMotion.answer("分かりました。",FullBodyPoseCatalog.Kind.NEUTRAL,2100);shortMotion.user("動いてない",8000);ok(shortMotion.motionType(8100)==ShyFidgetMotion.TYPE,"replay restarts short motion, "+initial);}
GestureRecency recency=new GestureRecency();ok(recency.allow(2,1000,false),"first ear");ok(recency.allow(2,1700,false),"same animation bout");ok(!recency.allow(3,8000,false),"same family suppressed");ok(recency.allow(0,9000,false),"different gesture");ok(!recency.allow(2,10000,false),"ear still cooled");ok(recency.allow(3,10000,true),"explicit request bypasses cooldown");ok(recency.allow(2,130001,false),"cooldown elapsed");
 PortraitAttentionMotion face=new PortraitAttentionMotion();face.mode(1,1000);ok(face.gaze(1900,false)<0&&face.tilt(1900,false)<0,"thinking look aside");face.mode(2,3000);ok(face.gaze(3300,false)>0&&face.nod(3300,false)>0,"answer looks back and nods");ok(face.gaze(3300,true)==0&&face.tilt(3300,true)==0&&face.nod(3300,true)==0,"quiet visual priority");ok(face.gaze(6000,false)==0&&face.nod(6000,false)==0,"answer gesture completes");
 System.out.println("PASS "+n+" continuity/replay/undo/recency/portrait checks");}
}
